    {
        try
        {
            _loading = true;
            _error = null;
            StateHasChanged();
            var result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
            SetResult(result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void SetResult(PagedResult<Product> result)
    {
        _result = result;
        _totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
